pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 prevPastBlockTime;
    uint256 prevBlockTimestamp;

    function setUp() public {
        c = new C();
        // Capture initial state before any fuzz operations
        prevPastBlockTime = c.pastBlockTime();
        prevBlockTimestamp = block.timestamp;
    }

    function testFuzz_property(uint256 _value, uint256 _timeAdvance) public {
        // Bound time advance to a reasonable range
        _timeAdvance = bound(_timeAdvance, 1, 1000);

        // Advance time
        vm.warp(block.timestamp + _timeAdvance);

        // Prepare value
        uint256 value = _value % 11 ether; // 0 to 10 ether range

        // Record state before call
        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBlockTimestamp = block.timestamp;

        // Ensure we have enough balance for the 10 ether requirement if needed
        if (value >= 10 ether) {
            vm.deal(address(c), 10 ether + 1); // ensure contract has ETH for transfer
            vm.deal(address(this), 10 ether);  // ensure caller has 10 ether
        }

        // Make the call with the given value
        (bool success, ) = address(c).call{value: value}("");

        // Record state after call
        uint256 afterPastBlockTime = c.pastBlockTime();
        uint256 afterBlockTimestamp = block.timestamp;

        // Rule: If the call succeeded (i.e., value == 10 ether and block.timestamp > beforePastBlockTime),
        // then the new pastBlockTime must satisfy: afterPastBlockTime - beforePastBlockTime == afterBlockTimestamp - beforeBlockTimestamp
        // This is because in the reference, pastBlockTime increases by exactly the timestamp increment.
        // The mutant adds an extra 1, breaking this equality.
        if (success) {
            assertTrue(afterPastBlockTime - beforePastBlockTime == afterBlockTimestamp - beforeBlockTimestamp,
                "pastBlockTime should increase by exactly the block timestamp difference");
        } else {
            // If call reverted, state must be unchanged
            assertTrue(afterPastBlockTime == beforePastBlockTime,
                "On revert, pastBlockTime must not change");
        }
    }
}

