        uint256 currentTime = block.timestamp;
        uint256 futureTime = currentTime + timeOffset + 1;
        vm.warp(futureTime);

        uint256 pastBefore = c.pastBlockTime();

        // Call fallback with exactly 10 ether, condition to not trigger the transfer
        // We need block.number % 15 != 0 to avoid transfer (which would reduce balance)
        // Since we cannot easily control block.number, we can just attempt the call
