        // Use deal to give contract enough balance for the require (msg.value == 10 ether)
        vm.deal(address(c), 10 ether);

        // But note: the fallback requires msg.value == 10 ether, so we send that
        // We don't need to check transfer condition for the invariant

        // Make the call
